                            END) as date_expired, b.users_id_from as status_check, b.users_id_to as status_notification, c.name as division_name, d.name as departement_name, e.name as departement_sub_name, e.type, g.name as position_name, h.name as contract_name, i.name as group_name, j.name as source_name, k.name as marital_name, l.name as religion_name
FROM `employees` `a`
LEFT JOIN `lnd_training_history` ON `lnd_training_history`.`employee_id` = `a`.`id`
LEFT JOIN `notifications` `b` ON `a`.`id` = `b`.`table_id` and `b`.`table_name` = 'employees'
JOIN `divisions` `c` ON `c`.`id` = `a`.`division_id`
JOIN `departements` `d` ON `d`.`id` = `a`.`departement_id`
JOIN `departement_subs` `e` ON `e`.`id` = `a`.`departement_sub_id`
JOIN `agreements` `f` ON `a`.`number` = `f`.`number` and `f`.`status` = 0
LEFT JOIN `positions` `g` ON `g`.`id` = `a`.`position_id`
LEFT JOIN `contracts` `h` ON `h`.`id` = `a`.`contract_id`
LEFT JOIN `groups` `i` ON `i`.`id` = `a`.`group_id`
LEFT JOIN `sources` `j` ON `j`.`id` = `a`.`source_id`
LEFT JOIN `maritals` `k` ON `k`.`id` = `a`.`marital_id`
LEFT JOIN `religions` `l` ON `l`.`id` = `a`.`religion_id`
WHERE `a`.`deleted` = 0
